// Pure collection logic. No network requests and no model-generated facts.
function validDay(value) {
  const s=String(value||'');
  return /^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(Date.parse(s+'T00:00:00Z'))&&new Date(s+'T00:00:00Z').toISOString().slice(0,10)===s;
}
function canonicalUrl(value) {
  const s=String(value||'').trim();
  const m=s.match(/^https?:\/\/([^\s/?#]+)([^#]*)/i);
  if(!m||m[1].includes('@')||m[1].includes(':'))return null;
  const host=m[1].toLowerCase();
  if(!host.includes('.')||/^(?:localhost|127\.|10\.|192\.168\.|169\.254\.|0\.)/.test(host)||/^172\.(?:1[6-9]|2\d|3[01])\./.test(host)||/\.(?:local|internal)$/.test(host))return null;
  const [path,query='']=m[2].split('?');
  const clean=query.split('&').filter(Boolean).filter(p=>!/^(?:utm_[^=]*|gclid|fbclid|mc_cid|mc_eid)=/i.test(p)).sort().join('&');
  return (s.toLowerCase().startsWith('https:')?'https://':'http://')+host+(path||'/').replace(/\/$/,'')+(clean?'?'+clean:'');
}
function sourceId(company,url) {
  const input=company.toLowerCase()+'|'+url; let hash=2166136261;
  for(let i=0;i<input.length;i++)hash=Math.imul(hash^input.charCodeAt(i),16777619)>>>0;
  return 'src-'+hash.toString(16).padStart(8,'0');
}
function publicationDate(result, retrievedAt) {
  const raw=result.iso_date||result.publication_date||result.date||'';
  if(validDay(raw))return {date:raw,status:'explicit_date_metadata',raw};
  const iso=/^\d{4}-\d{2}-\d{2}T/.test(raw);
  const named=/\b(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\b.*\b20\d{2}\b/i.test(raw);
  const us=/^\d{2}\/\d{2}\/20\d{2},/.test(raw);
  if((iso||named||us)&&Number.isFinite(Date.parse(raw))){
    const date=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(raw));
    return {date,status:'explicit_date_metadata',raw};
  }
  const relative=String(raw).match(/^(\d+)\s+(hour|day|week|month|minute)s?\s+ago$/i);
  return {date:null,status:relative?'relative_date_needs_review':'missing_or_ambiguous_date',raw};
}
function buildSearchJobs(context) {
  if(!validDay(context.window_start)||!validDay(context.window_end)||context.window_start>context.window_end)
    throw new Error('Research dates must be valid YYYY-MM-DD values in order');
  const add=(day,n)=>new Date(Date.parse(day+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);
  const topics=[
    ['cybersecurity','(cybersecurity OR "information security" OR "cyber incident" OR ransomware)'],
    ['leadership','(CIO OR CISO OR "chief information officer" OR "chief information security officer") (appointed OR joins OR departure OR named)'],
    ['contracts','("IT services" OR cybersecurity OR "security operations") (contract OR agreement OR partnership)'],
    ['technology','(cloud OR identity OR endpoint OR "OT security" OR SIEM) (deploys OR adopts OR pilot OR implementation)']
  ];
  const jobs=[];
  for(const company of context.companies)for(const [topic,terms] of topics) {
    const engine=topic==='cybersecurity'?'google_news':'google';
    jobs.push({job_id:'job-'+(jobs.length+1),company,topic,engine,
      query:'"'+company+'" '+terms+' after:'+add(context.window_start,-1)+' before:'+add(context.window_end,1),
      window_start:context.window_start,window_end:context.window_end});
  }
  return jobs;
}
function collectEvidence(context,jobs,responses) {
  const records=new Map(), failures=[],searches=[],dropped=[];
  const key=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
  const alias=company=>key(company.replace(/^the\s+/i,'').replace(/\b(?:company|corporation|corp|incorporated|inc|ltd|limited|plc)\b\.?/gi,''));
  function put(result,job,supplement=false) {
    const url=canonicalUrl(result.link||result.source_url);
    if(!url){dropped.push({company:job.company,reason:'Unsupported public source URL',title:result.title||''});return;}
    const title=String(result.title||'').trim();
    let body=String(supplement?result.evidence_text||'':result.snippet||result.description||'').trim();
    const rawSnippet=body;const ellipsis=body.search(/\.{3}|…/);
    if(!supplement&&ellipsis>=0&&(body.slice(0,ellipsis).match(/[·›]/g)||[]).length>=2)
      body=body.slice(ellipsis+(body[ellipsis]==='…'?1:3)).trim();
    const date=publicationDate(result,context.retrieved_at);
    const publisher=typeof result.source==='object'?result.source?.name||result.source?.title||'':result.source||result.publisher||'';
    const text=(title+' '+body+' '+publisher+' '+url);
    const nameMatch=alias(job.company).length>2&&key(text).includes(alias(job.company));
    const topicMatch=/\b(?:cyber\w*|security|ransomware|CIO|CISO|CTO|cloud|artificial intelligence|AI|machine learning|Microsoft|Azure|AWS|SAP|Salesforce|ServiceNow|identity|endpoint|SIEM|SOC|network|digital|technology|software|data platform|data center|information systems|information technology|IT services|chief information officer)\b/i.test(title+' '+body)||/\bIT\b/.test(title+' '+body);
    const issues=[];
    if(!date.date)issues.push(date.status);
    else if(date.date<context.window_start||date.date>context.window_end)issues.push('outside_research_window');
    if(!supplement&&!nameMatch)issues.push('company_match_needs_review');
    if(!supplement&&!topicMatch)issues.push('IT_cybersecurity_relevance_needs_review');
    if(body.length<20)issues.push('title_only_or_insufficient_excerpt');
    const evidenceLevel=supplement?'user_supplied_public_excerpt':body?'search_snippet':'search_title_only';
    const r={company:job.company,source_id:sourceId(job.company,url),source_url:url,title,publisher,
      publication_date:date.date,date_status:date.status,date_as_returned:date.raw,
      retrieved_at:context.retrieved_at,event_date:null,evidence_level:evidenceLevel,
      source_type:/\/(?:jobs?|careers)\//i.test(url)?'job_ad':'public_search_result',
      full_article_retrieved:false,source_publication_verified:false,
      snippet_cleaning:rawSnippet!==body?'navigation_prefix_removed':'none',
      evidence_text:body?title+'\n'+body:title,
      topics:[job.topic],provenance:[{job_id:job.job_id,engine:job.engine,query:job.query||''}],
      review_reasons:issues,eligible_for_agent3:issues.length===0,company_match:nameMatch?'lexical_only':'unconfirmed'};
    const id=job.company.toLowerCase()+'|'+url;
    if(records.has(id)) {
      const prior=records.get(id); const best=r.evidence_text.length>prior.evidence_text.length?r:prior;
      const other=best===r?prior:r;
      const merged={...best,topics:[...new Set([...prior.topics,...r.topics])],provenance:[...prior.provenance,...r.provenance]};
      if(!merged.publication_date&&other.publication_date){merged.publication_date=other.publication_date;merged.date_status=other.date_status;
        merged.review_reasons=merged.review_reasons.filter(s=>!['missing_or_ambiguous_date','relative_date_needs_review'].includes(s));}
      if(prior.publication_date&&r.publication_date&&prior.publication_date!==r.publication_date)
        merged.review_reasons=[...new Set([...merged.review_reasons,'conflicting_publication_dates'])];
      if(prior.review_reasons.includes('conflicting_publication_dates'))merged.review_reasons.push('conflicting_publication_dates');
      if(merged.publication_date&&(merged.publication_date<context.window_start||merged.publication_date>context.window_end))
        merged.review_reasons.push('outside_research_window');
      merged.review_reasons=[...new Set(merged.review_reasons)];
      merged.eligible_for_agent3=merged.review_reasons.length===0;
      records.set(id,merged);
    } else records.set(id,r);
  }
  for(let i=0;i<responses.length;i++) {
    const response=responses[i];const job=jobs.find(j=>j.query===response.search_parameters?.q)||response._job;
    if(!job){failures.push({job_id:null,error:'Search result could not be linked to its input query'});continue;}
    if(response.error){failures.push({job_id:job.job_id,company:job.company,topic:job.topic,engine:job.engine,error:typeof response.error==='string'?response.error:'Search failed'});continue;}
    const flat=[];
    function walk(list){for(const r of list||[]){if(r.link)flat.push(r);if(r.stories)walk(r.stories);if(r.highlight)walk([r.highlight]);}}
    walk(response.organic_results||response.news_results||[]);
    searches.push({...job,result_count:flat.length,retained_result_count:Math.min(flat.length,context.results_per_query)});
    for(const r of flat.slice(0,context.results_per_query))put(r,job);
  }
  const completed=new Set([...searches.map(s=>s.job_id),...failures.map(f=>f.job_id)]);
  for(const job of jobs)if(!completed.has(job.job_id))failures.push({...job,error:'Search response missing'});
  for(const r of context.supplemental_evidence||[]) {
    if(!context.companies.includes(r.company))continue;
    put(r,{company:r.company,topic:'supplemental',job_id:'manual',engine:'user_public_excerpt'},true);
  }
  const all=[...records.values()];
  const titleGroups=new Map();
  for(const r of all){const t=key(r.title);if(t.length<20)continue;const k=r.company+'|'+t;
    if(!titleGroups.has(k))titleGroups.set(k,[]);titleGroups.get(k).push(r.source_id);}
  for(const r of all){r.possible_syndication_ids=titleGroups.get(r.company+'|'+key(r.title))||[];}
  const ready=all.filter(r=>r.eligible_for_agent3).sort((a,b)=>b.publication_date.localeCompare(a.publication_date)||a.source_id.localeCompare(b.source_id));
  const review=all.filter(r=>!r.eligible_for_agent3);
  const coverage=context.companies.map(company=>({company,searches:searches.filter(s=>s.company===company).length,
    failed_searches:failures.filter(s=>s.company===company).length,records:all.filter(r=>r.company===company).length,
    ready_records:ready.filter(r=>r.company===company).length,
    topics:['cybersecurity','leadership','contracts','technology'].map(topic=>({topic,results:all.filter(r=>r.company===company&&r.topics.includes(topic)).length})),
    status:failures.some(f=>f.company===company)?'search_incomplete':all.some(r=>r.company===company)?'results_collected':'no_results_found'}));
  return {agent:2,status:failures.length?'partial':'collected',companies:context.companies,
    research_window:{start:context.window_start,end:context.window_end},retrieved_at:context.retrieved_at,
    coverage,searches,failed_searches:failures,evidence_records:ready,review_queue:review,dropped_results:dropped,
    statistics:{queries_planned:jobs.length,queries_succeeded:searches.length,queries_failed:failures.length,
      unique_sources:all.length,ready_for_agent3:ready.length,needs_review:review.length},
    analyze_with_agent3:context.analyze_with_agent3,max_analysis_records:context.max_analysis_records,
    limitations:['Search titles/snippets are public search evidence, not retrieved full articles.',
      'Dates come from search metadata or user-provided evidence and need original-source verification.',
      'Unknown dates, out-of-window results, weak company matches, and title-only records are held for review.',
      'Event dates are deliberately left unknown for Agent 3 to extract from evidence.',
      'Job advertisements are hiring evidence, not proof of deployed technology or leadership appointments.',
      'No login automation, private data access, scanning, or direct site-fetch requests are performed.']};
}

// Public professional background only. Model outputs are candidates, never independent evidence.
const bgKey=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const SEC_SCHOOLS=[['University of Alabama',['University of Alabama']],['University of Arkansas',['University of Arkansas']],['Auburn University',['Auburn University']],['University of Florida',['University of Florida']],['University of Georgia',['University of Georgia']],['University of Kentucky',['University of Kentucky']],['Louisiana State University',['Louisiana State University','LSU']],['University of Mississippi',['University of Mississippi','Ole Miss']],['Mississippi State University',['Mississippi State University']],['University of Missouri',['University of Missouri']],['University of Oklahoma',['University of Oklahoma']],['University of South Carolina',['University of South Carolina']],['University of Tennessee',['University of Tennessee']],['University of Texas at Austin',['University of Texas at Austin','University of Texas, Austin']],['Texas A&M University',['Texas A&M University','Texas A and M University']],['Vanderbilt University',['Vanderbilt University']]];
const FIRMS=[['Deloitte',['Deloitte','Deloitte Consulting']],['KPMG',['KPMG']],['EY',['Ernst & Young','Ernst and Young','EY']]];
function bgInput(input) {
 const name=String(input.person_name||input['Person name']||'').trim(),company=String(input.company_name||input['Company name']||'').trim();
 for(const [label,value] of [['person',name],['company',company]])if(value.length<3||value.length>120||/[\n\r"\\<>:]/.test(value)||/\b(?:password|address|phone|doxx|ssn)\b/i.test(value))throw Error('Enter a plain professional '+label+' name');
 if(name.split(/\s+/).length<2)throw Error('Enter the person’s full name to reduce mistaken identity');
 return {person_name:name,company_name:company,company_key:bgKey(company),retrieved_at:new Date().toISOString()};
}
function bgJobs(context){const base='"'+context.person_name+'" "'+context.company_name+'" ';
 return [['profile','biography leadership CIO CISO professional background'],['prior_firms','(Deloitte OR KPMG OR "Ernst & Young" OR EY) career worked'],['education','(education OR university OR degree OR graduated OR alumni)'],['linkedin_public','site:linkedin.com/in/']].map(([topic,terms],i)=>({...context,job_id:'bg-'+(i+1),topic,query:topic==='linkedin_public'?'site:linkedin.com/in/ '+base.trim():base+terms}));}
function bgCollect(context,jobs,responses){
 const sources=[],review=[],failures=[],seen=new Map();
 const companyAliases=[context.company_name,...(/^(?:procter.*gamble|p&g)$/i.test(context.company_name)?['P&G','Procter & Gamble']:[])].map(bgKey);
 for(let i=0;i<responses.length;i++){
  const response=responses[i],job=jobs.find(j=>j.query===response.search_parameters?.q)||jobs[i];
  if(response.error||!Array.isArray(response.organic_results)){failures.push({topic:job?.topic||'unknown',error:String(response.error?.message||response.error||'No organic result list')});continue;}
  for(const r of response.organic_results.slice(0,6)){
   const url=canonicalUrl(r.link);if(!url)continue;if(seen.has(url)){const existing=seen.get(url);if(job?.topic&&!existing.search_topics.includes(job.topic))existing.search_topics.push(job.topic);continue;}
   const host=url.match(/^https?:\/\/([^/]+)/i)[1];
   if(/(?:signalhire|rocketreach|zoominfo|contactout|apollo\.io|lusha|whitepages|spokeo|beenverified|peoplefinders|theorg\.com\/.*contact)/i.test(host)||/email|phone number|contact details/i.test(r.title||''))continue;
   const title=String(r.title||''),snippet=String(r.snippet||'').slice(0,2200),text=title+'\n'+snippet;
   const linkedProfile=/(?:^|\.)linkedin\.com$/i.test(host)&&/^https?:\/\/[^/]+\/in\//i.test(url);
   const reasons=[];if(job?.topic==='linkedin_public'&&!linkedProfile)reasons.push('Dedicated LinkedIn query returned a non-profile result');if(!bgKey(text).includes(bgKey(context.person_name)))reasons.push('Full person name not present');
   if(!companyAliases.some(a=>bgKey(text).includes(a)))reasons.push('Company context missing; identity needs review');
   if(!snippet.trim())reasons.push('No supporting excerpt');
   const record={source_id:sourceId(context.person_name,url),source_url:url,title,evidence_text:text,publication_date:r.date||'not found',retrieved_at:context.retrieved_at,evidence_level:'search_snippet',full_article_retrieved:false,review_reasons:reasons,source_type:linkedProfile?'linkedin_search_snippet':'public_search_result',search_topics:job?.topic?[job.topic]:[],profile_page_retrieved:false};
   seen.set(url,record);
   (reasons.length?review:sources).push(record);
  }
 }
 return {...context,sources,review_queue:review,search_failures:failures,search_count:jobs.length,identity_note:'Sources require full name and company context; name matches alone are not accepted. Same-name ambiguity still requires review.'};
}
function bgValidate(pack,raw){
 const data=raw?.output||raw||{},accepted=[],rejected=[];const clean=s=>String(s||'').replace(/\s+/g,' ').trim().toLowerCase();
 for(const claim of Array.isArray(data.claims)?data.claims:[]){
  const source=pack.sources.find(s=>s.source_id===claim.source_id),problems=[];
  const quote=clean(claim.evidence_excerpt),type=claim.category;
  if(/@|\b(?:wife|husband|children|spouse|home address|phone|birthplace|religion|political)\b/i.test(claim.statement||''))problems.push('Outside professional research scope');
  if(!source||claim.source_url!==source.source_url)problems.push('Source reference mismatch');
  if(!quote||quote==='not found'||!source||!clean(source.evidence_text).includes(quote))problems.push('Unsupported evidence quotation');
  if(!['professional_role','prior_firm','education'].includes(type))problems.push('Unsupported background category');
  if(/\b(?:may|might|could|perhaps|rumou?r|unconfirmed)\b/.test(quote))problems.push('Speculative evidence');
  let match=null;
  if(type==='prior_firm'){
   match=FIRMS.find(([name,aliases])=>bgKey(claim.organization)===bgKey(name)&&aliases.some(a=>new RegExp('\\b'+a.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i').test(quote)));
   if(!match||!/\b(?:worked|working|joined|career|served|consultant|manager|partner|employment|employed|auditor|director|at deloitte|at kpmg|at ernst|at ey)\b/.test(quote))problems.push('Explicit employment at requested firm not established');
   if(/\b(?:award|awards|panel|sponsored|speaker|conference)\b/.test(quote)&&!/\b(?:worked at|employed by|joined|served at)\b/.test(quote))problems.push('Award or event association is not employment');
   if(/\b(?:client|customer|vendor|partnership|advises|advised)\b/.test(quote)&&!/\b(?:worked at|employed by|joined|served at)\b/.test(quote))problems.push('Client/vendor relationship is not employment');
  }
  if(type==='education'){
   if(!/\b(?:degree|graduate|graduated|alumn|bachelor|master|mba|phd|education|studied|attended|earned|holds)\w*\b/.test(quote))problems.push('Attendance or education relationship not established');
   if(!bgKey(quote).includes(bgKey(claim.organization)))problems.push('Named institution absent from quotation');
   if(/\b(?:spoke|speaker|sponsor|sponsored|conference|client|recruiter)\b/.test(quote)&&!/\b(?:graduated|earned|degree|studied|attended as a student)\b/.test(quote))problems.push('Speaking or business relationship is not attendance');
   if(/\bhonorary\b/.test(quote))problems.push('Honorary degree does not establish attendance');
   if(/university of alabama (?:at )?(?:birmingham|huntsville)|university of tennessee (?:at )?(?:chattanooga|martin)|university of missouri[ -](?:st\.? louis|kansas city)|lsu (?:shreveport|alexandria)|louisiana state university (?:at )?(?:shreveport|alexandria)/i.test(quote))problems.push('Separate campus cannot establish SEC school attendance');
   match=SEC_SCHOOLS.find(([name,aliases])=>aliases.some(a=>bgKey(a)===bgKey(claim.organization)));
  }
  if(type==='professional_role'&&(!claim.organization||!bgKey(quote).includes(bgKey(claim.organization))||!/\b(?:chief|officer|director|president|head|manager|partner|cio|ciso|cto|leads?|led|appointed|joined|serves?|served)\b/.test(quote)))problems.push('Explicit professional role not established');
  const value={...claim,evidence_level:'search_snippet',verification_status:'needs_original_source_verification',sec_school:type==='education'?(match?match[0]:null):null,sec_membership_basis:type==='education'?'Current SEC member school list as of 2026-10-25; does not establish sports participation or membership at time of attendance':null};
  (problems.length?rejected:accepted).push(problems.length?{...value,rejection_reasons:problems}:value);
 }
 const unique=[...new Map(accepted.map(c=>[[c.category,bgKey(c.organization),bgKey(c.statement),c.source_id].join('|'),c])).values()];
 const firmMatches=unique.filter(c=>c.category==='prior_firm'),education=unique.filter(c=>c.category==='education');
 const profile={agent:4,...pack,analysis_status:data.error||raw?.error?'failed':'complete',error:data.error||raw?.error||null,claims:unique,rejected_claims:rejected,
  linkedin_profiles:pack.sources.filter(s=>s.source_type==='linkedin_search_snippet').map(s=>({person_name:pack.person_name,source_id:s.source_id,source_url:s.source_url,title:s.title,evidence_level:'search_snippet',profile_page_retrieved:false,verification_status:'needs_profile_verification'})),
  requested_firm_experience:{status:firmMatches.length?'supported_by_snippet':'not found',matches:firmMatches},sec_education:{status:education.some(c=>c.sec_school)?'supported_by_snippet':'not found',matches:education.filter(c=>c.sec_school)},
  limitations:['Public professional background only; no contact details, family information, personal addresses, or private data collected.','Search snippets are preliminary evidence; current roles, employment and education need original-source verification.','Not found means insufficient supplied evidence, not proof of no experience or attendance.','Background research is historical and is not restricted to the three-month news window.','SEC attendance does not imply playing football or any other sport.']};
 profile.background_markdown='**'+pack.person_name+' — '+pack.company_name+'**\n'+(unique.length?unique.map(c=>'- '+c.statement+' — ['+c.organization+'](<'+c.source_url+'>) · needs source verification').join('\n'):'No supported professional background claims found in the supplied excerpts.');
 if(profile.linkedin_profiles.length)profile.background_markdown+='\n\nPublic LinkedIn search results:\n'+profile.linkedin_profiles.map(p=>'- ['+p.title.replace(/[\[\]]/g,'')+'](<'+p.source_url+'>) · search snippet only').join('\n');
 return profile;
}

const LEADER_ROLES=['CEO','CISO','CTO','CIO'];
function leaderInput(input){const company=String(input.company_name||input['Company name']||'').trim();if(company.length<3||company.length>120||/[\n\r"\\<>:]/.test(company))throw Error('Enter a plain company name');return {company_name:company,company_key:bgKey(company),retrieved_at:new Date().toISOString()};}
function leaderJobs(context){return LEADER_ROLES.map(role=>({...context,role,query:'"'+context.company_name+'" ("'+role+'" OR "'+({CEO:'chief executive officer',CISO:'chief information security officer',CTO:'chief technology officer',CIO:'chief information officer'}[role])+'")'}));}
function leaderCollect(context,jobs,responses){const sources=[],failures=[],seen=new Set();for(let i=0;i<responses.length;i++){const response=responses[i],job=jobs.find(j=>j.query===response.search_parameters?.q)||jobs[i];if(response.error||!Array.isArray(response.organic_results)){failures.push({role:job?.role,error:String(response.error?.message||response.error||'No results')});continue;}for(const r of response.organic_results.slice(0,5)){const url=canonicalUrl(r.link);if(!url||seen.has(url)||/signalhire|rocketreach|zoominfo|contactout|apollo\.io|lusha|whitepages|spokeo|beenverified/i.test(url))continue;seen.add(url);sources.push({source_id:sourceId(context.company_name,url),source_url:url,title:r.title||'',evidence_text:(r.title||'')+'\n'+(r.snippet||''),publication_date:r.date||'not found',queried_role:job?.role,evidence_level:'search_snippet'});}}return {...context,sources,discovery_failures:failures};}
function leaderValidate(pack,raw){const data=raw.output||raw,leaders=[],rejected=[];const clean=s=>String(s||'').replace(/\s+/g,' ').trim().toLowerCase();
 for(const candidate of Array.isArray(data.leaders)?data.leaders:[]){const reasons=[],source=pack.sources.find(s=>s.source_id===candidate.source_id);const q=clean(candidate.evidence_excerpt);const fullname=String(candidate.person_name||'').trim();
 if(!LEADER_ROLES.includes(candidate.role)||fullname.split(/\s+/).length<2||!bgKey(q).includes(bgKey(fullname)))reasons.push('Full name and requested role required in evidence');
 if(!source||source.source_url!==candidate.source_url||!clean(source.evidence_text).includes(q)||!q)reasons.push('Unsupported source or quotation');
